INSERT OR IGNORE INTO church_document_contents (doc_id,html,updated_at,updated_by) VALUES ('cdoc-representative-03','<table class="auto"><tr><td colspan="3" rowspan="3"><p></p></td><td colspan="11"><p>이 력 서</p></td></tr><tr><td colspan="3"><p>한글성명</p></td><td colspan="3"><p>정찬균</p></td><td colspan="2"><p>생년월일</p></td><td colspan="3"><p>1977년 10월 19일(만 45세)</p></td></tr><tr><td colspan="3"><p>주 소</p></td><td colspan="8"><p>전남 무안군 청계면 백련동 1길 17-4 건물 1층 (010-3501-8542)</p></td></tr><tr><td rowspan="7"><p>학</p><p>력</p></td><td><p>구분</p></td><td colspan="5"><p>기 간</p></td><td colspan="6"><p>학 교 명</p></td><td><p>비고</p></td></tr><tr><td><p>고교</p></td><td colspan="5"><p>1993.03 ~ 1996.02</p></td><td colspan="6"><p>벌교고등학교</p></td><td><p>졸업</p></td></tr><tr><td><p>대학</p></td><td colspan="5"><p>1996.03 ~ 2003.02</p></td><td colspan="6"><p>목포대학교 경영학과 학사</p></td><td><p>졸업</p></td></tr><tr><td><p>대학원</p></td><td colspan="5"><p>2008.09 ~ 2013.08</p></td><td colspan="6"><p>목포대학교 경영학과 석사</p></td><td><p>졸업</p></td></tr><tr><td><p>대학</p></td><td colspan="5"><p>2013.03 ~ 2014.06</p></td><td colspan="6"><p>문화체육관광부 한국어교원학</p></td><td><p>졸업</p></td></tr><tr><td><p>대학원</p></td><td colspan="5"><p>2015.03 ~ 2017.02</p></td><td colspan="6"><p>목포대학교 경영학과 박사</p></td><td><p>수료</p></td></tr><tr><td><p></p></td><td colspan="5"><p></p></td><td colspan="6"><p></p></td><td><p></p></td></tr><tr><td rowspan="3"><p>가</p><p>족</p></td><td colspan="3"><p>성명</p></td><td><p>관계</p></td><td colspan="3"><p>직업</p></td><td colspan="3"><p>성명</p></td><td colspan="2"><p>관계</p></td><td><p>직업</p></td></tr><tr><td colspan="3"><p>박은희</p></td><td><p>배우자</p></td><td colspan="3"><p>주부</p></td><td colspan="3"><p>정성</p></td><td colspan="2"><p>녀</p></td><td><p>고등학교 2</p></td></tr><tr><td colspan="3"><p>정진</p></td><td><p>자</p></td><td colspan="3"><p>대학교 1</p></td><td colspan="3"><p>정결</p></td><td colspan="2"><p>자</p></td><td><p>중학교 3</p></td></tr><tr><td rowspan="9"><p>주</p><p>요</p><p>경</p><p>력</p></td><td colspan="4"><p>기 간</